"""Config dict merging."""

from collections.abc import Mapping


def _deep_copy(value):
    """Return a deep copy of *value* without sharing nested containers.

    Immutable scalars are returned as-is; dicts and lists (and any nested
    containers inside them) are recreated so the result never shares
    mutable objects with the input.
    """
    if isinstance(value, dict):
        return {key: _deep_copy(item) for key, item in value.items()}
    if isinstance(value, Mapping):
        return {key: _deep_copy(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_deep_copy(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_deep_copy(item) for item in value)
    if isinstance(value, set):
        return set(value)
    return value


def deep_merge(base, override):
    """Recursively merge ``override`` into ``base``.

    Neither ``base`` nor ``override`` is modified and the returned dict
    shares no nested dict/list objects with either input.

    Rules:
      * nested dicts are merged recursively (at any depth)
      * lists are concatenated
      * when one side holds a dict and the other does not, the value from
        ``override`` wins
      * a ``None`` value in ``override`` removes the key from the result
    """
    if not isinstance(base, Mapping):
        return _deep_copy(override)
    if not isinstance(override, Mapping):
        return _deep_copy(base)

    result = _deep_copy(base)
    for key, value in override.items():
        if value is None:
            result.pop(key, None)
            continue
        current = result.get(key)
        if isinstance(value, Mapping) and isinstance(current, Mapping):
            result[key] = deep_merge(current, value)
        elif isinstance(value, list) and isinstance(current, list):
            merged = list(current)
            merged.extend(_deep_copy(value))
            result[key] = merged
        else:
            result[key] = _deep_copy(value)
    return result
EOF
